namespace ShipmentTracker.Client.Services;

using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

public class ShipmentHttpService(HttpClient http) : IShipmentService
{
    public async Task<List<Shipment>> GetAllShipmentsAsync()
        => await http.GetFromJsonAsync<List<Shipment>>("api/shipments") ?? [];

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
        => await http.GetFromJsonAsync<Shipment?>($"api/shipments/track/{trackingNumber}");

    public async Task<List<Shipment>> GetShipmentsByCustomerAsync(string email)
        => await http.GetFromJsonAsync<List<Shipment>>($"api/shipments/customer/{Uri.EscapeDataString(email)}") ?? [];

    public async Task UpdateShipmentStatusAsync(int id, ShipmentStatus status)
        => await http.PutAsJsonAsync($"api/shipments/{id}/status", status);

    public async Task<Shipment> CreateShipmentAsync(Shipment shipment)
    {
        var response = await http.PostAsJsonAsync("api/shipments", shipment);
        response.EnsureSuccessStatusCode();
        return (await response.Content.ReadFromJsonAsync<Shipment>())!;
    }
}
```

### 4. Server-side service implementation (uses EF Core)
Create `ShipmentTracker/Services/ShipmentServerService.cs`:
```csharp
namespace ShipmentTracker.Services;

using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

public class ShipmentServerService(ApplicationDbContext db) : IShipmentService
{
    public async Task<List<Shipment>> GetAllShipmentsAsync()
        => await db.Shipments.OrderByDescending(s => s.CreatedAt).ToListAsync();

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
        => await db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);

    public async Task<List<Shipment>> GetShipmentsByCustomerAsync(string email)
        => await db.Shipments.Where(s => s.CustomerEmail == email).OrderByDescending(s => s.CreatedAt).ToListAsync();

    public async Task UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        var shipment = await db.Shipments.FindAsync(id);
        if (shipment is not null)
        {
            shipment.Status = status;
            await db.SaveChangesAsync();
        }
    }

    public async Task<Shipment> CreateShipmentAsync(Shipment shipment)
    {
        shipment.TrackingNumber = $"SHP-{Guid.NewGuid().ToString()[..8].ToUpper()}";
        shipment.CreatedAt = DateTime.UtcNow;
        db.Shipments.Add(shipment);
        await db.SaveChangesAsync();
        return shipment;
    }
}
```

