        => await db.Shipments.OrderByDescending(s => s.CreatedAt).ToListAsync();

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
        => await db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);

    public async Task<List<Shipment>> GetShipmentsByCustomerAsync(string email)
        => await db.Shipments.Where(s => s.CustomerEmail == email).OrderByDescending(s => s.CreatedAt).ToListAsync();

